<?php use App\Support\Http;use App\Controllers\AuthController; ?>
<section class="card border-0 shadow-sm mt-4"><div class="card-body"><h2 class="h4"><?= \App\Support\I18n::html('My assigned stock') ?></h2><div class="table-responsive"><table class="table"><thead><tr><th><?= \App\Support\I18n::html('Product') ?></th><th><?= \App\Support\I18n::html('Available quantity') ?></th><th><?= \App\Support\I18n::html('Selling price (LKR)') ?></th></tr></thead><tbody><?php foreach($assignedStock['rows'] as $row): ?><tr><td><?= Http::escape($row['sku'].' / '.\App\Support\I18n::product($row)) ?></td><td><?= Http::escape((string)$row['quantity']) ?></td><td><?= Http::escape($row['selling_price']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$assignedStock['rows']): ?><p><?= \App\Support\I18n::html('No stock has been allocated to you.') ?></p><?php endif; ?><a href="<?= Http::escape(AuthController::url('/rep/stock')) ?>"><?= \App\Support\I18n::html('View all my stock') ?></a></div></section>
<section class="card border-0 shadow-sm mt-4"><div class="card-body"><h2 class="h4"><?= \App\Support\I18n::html('My allocation history') ?></h2><div class="table-responsive"><table class="table"><thead><tr><th><?= \App\Support\I18n::html('Date (Asia/Colombo)') ?></th><th><?= \App\Support\I18n::html('Product') ?></th><th><?= \App\Support\I18n::html('Change') ?></th><th><?= \App\Support\I18n::html('Quantity after') ?></th></tr></thead><tbody><?php foreach($allocationHistory['rows'] as $row): ?><tr><td><?= Http::escape((new DateTimeImmutable($row['created_at_utc'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Colombo'))->format('Y-m-d H:i:s')) ?></td><td><?= Http::escape($row['sku'].' / '.\App\Support\I18n::product($row)) ?></td><td><?= $row['type']==='TRANSFER'?((int)$row['quantity_delta']>0?\App\Support\I18n::html('Allocated'):\App\Support\I18n::html('Returned')):\App\Support\I18n::html('Correction') ?> <?= Http::escape((string)$row['quantity_delta']) ?></td><td><?= Http::escape((string)$row['quantity_after']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$allocationHistory['rows']): ?><p><?= \App\Support\I18n::html('No stock history yet.') ?></p><?php endif; ?><a href="<?= Http::escape(AuthController::url('/rep/stock/history')) ?>"><?= \App\Support\I18n::html('View all my allocation history') ?></a></div></section>
